        new("mask","field:799d4dc194af5bab824d2a1555967ff4","field:37d5d958f3e2566e843a87bc424fa053","field:fafe9d65445d55aaaea811c2916cf058","field:4ff1aa26d3f1517a9a2ffba7dab097df"),
    };
    internal static FieldPresentation Presentation(BlobInputField field,string? label=null,string? group=null,IReadOnlyDictionary<string,string>? labels=null)
        =>new(field.Port.Id,label??field.Presentation.DisplayName,group??field.Presentation.Group,field.Presentation.Order,
            field.Presentation.Editor,field.Presentation.ChoiceKeys,labels??field.Presentation.ChoiceLabels)
            {Layout=Runtime.BlobPresentation.Layout(field.LogicalKey,FieldIds)};
    private static readonly IReadOnlyDictionary<string,string> FieldIds=Entries.ToDictionary(field=>field.LogicalKey,field=>field.Port.Id,StringComparer.Ordinal);
    public static ToolSchema Describe()=>new(Entries.Select(field=>field.Port),BlobOutputContract.Describe().Select(SunEyeVision.Plugin.SDK.Execution.Parameters.BindingClrAdapter.DescribeOutput),
        new ToolPresentation(Entries.Select(field=>Presentation(field)),false,Regions));
    public static IReadOnlyDictionary<string,ParameterSetting> CreateDefaults()
    {
        var defaults=new BlobAnalysisParameters();
        return new ReadOnlyDictionary<string,ParameterSetting>(Entries.ToDictionary(field=>field.Port.Id,field=>field.Default(defaults),StringComparer.Ordinal));
    }
    public static IReadOnlyList<Diagnostic> ValidateStoredConfiguration(BlobAnalysisParameters settings,IReadOnlyCollection<string>? boundParameterNames=null)
    {
        var issues=new List<Diagnostic>();
        if(boundParameterNames?.Contains("SegmentationMode",StringComparer.Ordinal)==true)issues.Add(new("stored-setting","分割方式仅允许常量选择，不能订阅运行值。"));
        if(settings.ResultPresentation is null)return Array.AsReadOnly(new[]{new Diagnostic("stored-setting","ResultPresentation must be present.")});
        void ValidateKeys(string collection,IEnumerable<string>? supplied,string[] expected)
        {
            var keys=supplied?.ToArray();
            if(keys is null||keys.Length!=expected.Length||keys.Distinct(StringComparer.Ordinal).Count()!=keys.Length
                ||!keys.ToHashSet(StringComparer.Ordinal).SetEquals(expected))
                issues.Add(new("stored-setting",collection+" has missing, duplicate or unknown entries; an explicit schema migration is required."));
        }
        ValidateKeys("ResultPresentation.Judgments",settings.ResultPresentation.Judgments?.Select(item=>item?.Key??""),new[]{"output-not-empty","white-ratio","blob-count","total-area","average-area","max-area","min-area","average-circularity","average-rectangularity","per-blob-area","per-blob-circularity","per-blob-rectangularity"});
        ValidateKeys("ResultPresentation.Graphics",settings.ResultPresentation.Graphics?.Select(item=>item?.Key??""),new[]{"blobs","centroids","contours","inspection-roi","mask-roi"});
        ValidateKeys("ResultPresentation.Texts",settings.ResultPresentation.Texts?.Select(item=>item?.Key??""),new[]{"area"});
        foreach(var field in Entries)
        {
            // Reference expressions are validated by the workflow owner. Do not resolve runtime sources during persistence.
            if(!settings.IsBindingInputActive(field.LegacyPath)||boundParameterNames?.Contains(field.LegacyPath,StringComparer.Ordinal)==true)continue;
            try{field.ValidateLiteral(settings);}
            catch(Exception error) when(error is ArgumentException or InvalidOperationException or NullReferenceException)
            {issues.Add(new("stored-setting",field.LegacyPath+": "+error.Message,field.Port.Id));}
        }
        return issues.AsReadOnly();
    }
}
